--
-- Name: workspace_grants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_grants (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    account_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_grants_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'member'::text])))
);


--
-- Name: workspace_provider_credentials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_provider_credentials (
    workspace_id uuid NOT NULL,
    provider text NOT NULL,
    ciphertext text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_provider_credentials_provider_check CHECK ((provider = ANY (ARRAY['openai'::text, 'openai-compatible'::text, 'gemini'::text, 'claude'::text])))
);


--
-- Name: workspace_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    account_id uuid NOT NULL,
    token_prefix text NOT NULL,
    token_hash text NOT NULL,
    encrypted_token text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    revoked_at timestamp with time zone
);


--
-- Name: workspace_webhook_destinations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_webhook_destinations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    name text NOT NULL,
    url text NOT NULL,
    secret_ciphertext text NOT NULL,
    encryption_key_id text NOT NULL,
    last_delivery_status text,
    last_delivery_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_webhook_destinations_name_check CHECK ((NULLIF(btrim(name), ''::text) IS NOT NULL)),
    CONSTRAINT workspace_webhook_destinations_url_check CHECK ((NULLIF(btrim(url), ''::text) IS NOT NULL)),
    CONSTRAINT workspace_webhook_destinations_url_check1 CHECK (((url ~* '^https://'::text) OR (url ~* '^http://(([a-z0-9-]+\.)*localhost|127\.0\.0\.1|\[::1\]|host\.docker\.internal)(:[0-9]+)?(/|$)'::text)))
);


--
-- Name: workspaces; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    anonymous_chat_enabled boolean DEFAULT false NOT NULL,
    anonymous_chat_token text,
    anonymous_rate_limit integer DEFAULT 10 NOT NULL,
    assistant_name text DEFAULT ''::text NOT NULL,
    greeting_instruction text DEFAULT ''::text NOT NULL,
    assistant_default_locale text,
    proactive_greeting_enabled boolean DEFAULT false NOT NULL,
    website_embed_enabled boolean DEFAULT false NOT NULL,
    website_embed_token text,
    website_embed_allowed_origins text[] DEFAULT '{}'::text[] NOT NULL,
    website_embed_launcher_label text DEFAULT 'Chat with us'::text NOT NULL,
    website_embed_launcher_icon text DEFAULT 'chat'::text NOT NULL,
    website_embed_launcher_position text DEFAULT 'bottom-right'::text NOT NULL,
    public_route_key text NOT NULL,
    default_agent_id uuid
);


